const inputData = $input.first().json;

// El webhook de n8n entrega los datos dentro de "body". 
// Esta línea asegura que lo tomamos de ahí, o de la raíz si cambia.
const data = inputData.body || inputData;

const ticket = data.ticket || {};
const solicitante = data.solicitante || {};

const asunto = ticket.asunto || data.asunto || 'Sin asunto';
const descripcion = ticket.descripcion || data.descripcion || 'Sin descripción';
const categoria = ticket.categoria?.nombre || data.categoria || 'Sin categoría';
const prioridad = ticket.prioridad?.nombre || data.prioridad || 'Sin prioridad';
const estado = ticket.estado || data.estado || 'nuevo';

const nombre = solicitante.nombre || data.nombre || 'Usuario desconocido';
const email = solicitante.email || data.email || 'Sin email';
const area = solicitante.area || data.area || 'Sin área';

// Extracción robusta: si existe, lo toma; si no, usa el fallback.
const ticketId = data.ticket_id !== undefined ? data.ticket_id : 'UNKNOWN_ID';
const backendUrl = data.backend_url || 'http://localhost:8000/api';

// DEBUG: Esto aparecerá en la pestaña "Console" del nodo para que verifiques que lo lee bien
console.log('🔍 DEBUG Preparar Prompt -> ticket_id:', ticketId, '| backend_url:', backendUrl);

const systemPrompt = `Eres un asistente de soporte técnico especializado en análisis de tickets. Responde EXCLUSIVAMENTE con un objeto JSON válido, sin markdown ni texto adicional.`;

const userPrompt = `Se ha recibido un nuevo ticket con los siguientes datos:

📌 ASUNTO: ${asunto}
📝 DESCRIPCIÓN: ${descripcion}
📂 CATEGORÍA: ${categoria}
⚡ PRIORIDAD: ${prioridad}
👤 SOLICITANTE: ${nombre}
🏢 ÁREA: ${area}
📧 EMAIL: ${email}
📝 ESTADO: ${estado}

IMPORTANTE: Debes responder EXCLUSIVAMENTE en el siguiente formato JSON:
{
  "id_categoria": 2,
  "id_prioridad": 3,
  "confianza": 0.95,
  "justificacion": "Breve razón de la clasificación"
}

MAPA DE CATEGORÍAS (id_categoria):
1 = Hardware, 2 = Software, 3 = Red, 4 = Cuentas/Accesos, 5 = Otros

MAPA DE PRIORIDADES (id_prioridad):
1 = crítica, 2 = alta, 3 = media, 4 = baja

Responde SOLO con el JSON.`;

return [{
  json: {
    model: 'llama3.2',
    messages: [
      { "role": "system", "content": systemPrompt },
      { "role": "user", "content": userPrompt }
    ],
    stream: false,
    format: "json",
    temperature: 0.1,
    ticket_id: ticketId,
    backend_url: backendUrl
  }
}];

const ollamaResponse = $input.first().json;
const rawContent = ollamaResponse.message?.content || '{}';
const modelName = ollamaResponse.model || 'llama3.2';

console.log('🤖 Respuesta cruda de Ollama:', rawContent);

let ticketId = 'UNKNOWN_ID';
let backendUrl = 'http://localhost:8000/api';

try {
  // ¡CLAVE DEL ÉXITO! Recuperamos los datos del nodo anterior por su nombre exacto
  const promptData = $('Preparar Prompt').first().json;
  ticketId = promptData.ticket_id !== undefined ? promptData.ticket_id : 'UNKNOWN_ID';
  backendUrl = promptData.backend_url || 'http://localhost:8000/api';
  console.log('✅ ÉXITO: Datos recuperados de "Preparar Prompt" -> Ticket ID:', ticketId);
} catch (e) {
  console.error('❌ ERROR al recuperar datos del nodo "Preparar Prompt":', e.message);
  console.log('⚠️ Asegúrate de que el nodo anterior se llame EXACTAMENTE "Preparar Prompt" (sin el 1 y sin espacios al final).');
}

let analysis = {};
try {
  // Limpiar posibles bloques de markdown que a veces Ollama añade
  const cleanContent = rawContent.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  analysis = JSON.parse(cleanContent);
} catch (e) {
  console.error('Error parseando JSON, usando fallback:', e.message);
  analysis = {
    id_categoria: 5,
    id_prioridad: 3,
    confianza: 0.5,
    justificacion: 'Fallback por error de parseo'
  };
}

return [{
  json: {
    ticket_id: ticketId,
    callback_url: `${backendUrl}/tickets/${ticketId}/ai-analysis`,
    ai_analysis_payload: {
      id_categoria: analysis.id_categoria,
      id_prioridad: analysis.id_prioridad,
      confianza: analysis.confianza || 0.8,
      modelo_ia: modelName,
      tokens_usados: ollamaResponse.eval_count || 0,
      tiempo_ejecucion_ms: Math.round((ollamaResponse.total_duration || 0) / 1000000)
    }
  }
}];
